import type { FloatProps } from "./float.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Float";

// Generate child element class names for the component, should match available style slots
export const FloatClasses = {
  root: "exp-textura_float",
  content: "exp-textura_float_content",
  anchor: "exp-textura_float_anchor",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: FloatProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<FloatProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    position: "relative",
    display: "flex",
    alignItems: "center",
    width: "fit-content",

    [`.${FloatClasses.content}`]: {
      position: "absolute",
      zIndex: 1,
      "&[data-placement=top-start]": {
        top: props.offSetY,
        insetInlineStart: props.offSetX,
        transform: "translate(-50%, -50%)",
        ":dir(rtl)": {
          transform: "translate(50%, -50%)",
        },
      },
      "&[data-placement=top-center]": {
        top: props.offSetY,
        left: "50%",
        transform: "translate(-50%, -50%)",
      },
      "&[data-placement=top-end]": {
        top: props.offSetY,
        insetInlineEnd: props.offSetX,
        transform: "translate(50%, -50%)",
        ":dir(rtl)": {
          transform: "translate(-50%, -50%)",
        },
      },
      "&[data-placement=bottom-start]": {
        bottom: props.offSetY,
        insetInlineStart: props.offSetX,
        transform: "translate(-50%, 50%)",
        ":dir(rtl)": {
          transform: "translate(50%, 50%)",
        },
      },
      "&[data-placement=bottom-center]": {
        bottom: props.offSetY,
        left: "50%",
        transform: "translate(-50%, 50%)",
      },
      "&[data-placement=bottom-end]": {
        bottom: props.offSetY,
        insetInlineEnd: props.offSetX,
        transform: "translate(50%, 50%)",
        ":dir(rtl)": {
          transform: "translate(-50%, 50%)",
        },
      },
      "&[data-placement=middle-start]": {
        top: "50%",
        insetInlineStart: props.offSetX,
        transform: "translate(-50%, -50%)",
        ":dir(rtl)": {
          transform: "translate(50%, -50%)",
        },
      },
      "&[data-placement=middle-center]": {
        top: "50%",
        left: "50%",
        transform: "translate(-50%, -50%)",
      },
      "&[data-placement=middle-end]": {
        top: "50%",
        insetInlineEnd: props.offSetX,
        transform: "translate(50%, -50%)",
        ":dir(rtl)": {
          transform: "translate(-50%, -50%)",
        },
      },
      ...styleSlots?.content,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps("offSetX", "offSetY");

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledFloat = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<FloatProps>((props) => generateStyles(props));
